create or replace function public.update_hr_employee_v1(p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint,p_employment_id bigint,p_display_name text,p_name_native text default null,p_gender text default null,p_preferred_locale text default 'en',p_department_key text default null,p_designation text default 'Staff Member',p_contract_type text default 'permanent',p_qualification_summary text default null,p_payroll_eligible boolean default true,p_state text default 'active') returns jsonb language plpgsql set search_path to '' as $fn$
declare v_membership bigint;v_employment public.hr_employments%rowtype;v_department text;v_designation_key text;v_profile_employment_type text;v_state text:=lower(btrim(coalesce(p_state,'')));
begin
if length(btrim(coalesce(p_display_name,'')))<2 or length(btrim(p_display_name))>160 then raise exception 'employee name is invalid'; end if;
if p_gender is not null and p_gender not in ('male','female','other','undisclosed') then raise exception 'employee gender is invalid'; end if;
if p_preferred_locale not in ('en','ur','ar') then raise exception 'preferred locale is invalid'; end if;
if p_contract_type not in ('permanent','fixed_term','part_time','casual','volunteer','consultant') then raise exception 'contract type is invalid'; end if;
if v_state not in ('active','on_leave','suspended') then raise exception 'ordinary employee edit cannot perform separation or archive'; end if;
if length(btrim(coalesce(p_designation,'')))<2 or length(btrim(p_designation))>120 then raise exception 'designation is invalid'; end if;
if p_qualification_summary is not null and length(p_qualification_summary)>1000 then raise exception 'qualification summary is too long'; end if;
select m.id into v_membership from public.memberships m where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active' and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id)) and exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.manage') order by m.created_at limit 1;
if v_membership is null then raise exception 'employee management permission denied'; end if;
select * into v_employment from public.hr_employments e where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and e.id=p_employment_id and e.state not in ('separated','archived') for update;
if not found then raise exception 'editable employee not found in active branch'; end if;
v_department:=nullif(regexp_replace(lower(btrim(coalesce(p_department_key,''))),'[^a-z0-9]+','_','g'),'');v_designation_key:=trim(both '_' from regexp_replace(lower(btrim(p_designation)),'[^a-z0-9]+','_','g'));v_profile_employment_type:=case p_contract_type when 'part_time' then 'part_time' when 'volunteer' then 'volunteer' when 'casual' then 'contract' when 'consultant' then 'contract' else 'full_time' end;
update public.persons set display_name=btrim(p_display_name),name_native=nullif(btrim(coalesce(p_name_native,'')),''),gender=p_gender,preferred_locale=p_preferred_locale,updated_at=clock_timestamp() where tenant_id=p_tenant_id and id=v_employment.employee_person_id;
update public.employee_profiles set department_key=v_department,designation=btrim(p_designation),employment_type=v_profile_employment_type,status=case when v_state='suspended' then 'suspended' when v_state='on_leave' then 'leave' else 'active' end,qualification_summary=nullif(btrim(coalesce(p_qualification_summary,'')),''),updated_at=clock_timestamp() where tenant_id=p_tenant_id and person_id=v_employment.employee_person_id;
update public.hr_employments set department_key=v_department,designation_key=v_designation_key,contract_type=p_contract_type,payroll_eligible=p_payroll_eligible,state=v_state,updated_at=clock_timestamp() where tenant_id=p_tenant_id and id=p_employment_id;
insert into public.audit_events(tenant_id,branch_id,actor_identity_id,actor_membership_id,action,outcome,entity_type,entity_id,correlation_id,before_state,after_state) values(p_tenant_id,p_branch_id,p_identity_id,v_membership,'hr.employee.update','succeeded','hr_employment',p_employment_id::text,gen_random_uuid(),jsonb_build_object('department_key',v_employment.department_key,'designation_key',v_employment.designation_key,'contract_type',v_employment.contract_type,'state',v_employment.state,'payroll_eligible',v_employment.payroll_eligible),jsonb_build_object('department_key',v_department,'designation_key',v_designation_key,'contract_type',p_contract_type,'state',v_state,'payroll_eligible',p_payroll_eligible));
return jsonb_build_object('employment_id',p_employment_id,'person_id',v_employment.employee_person_id,'employee_number',v_employment.employee_number,'state',v_state);end;$fn$;
revoke all on function public.update_hr_employee_v1(uuid,bigint,bigint,bigint,text,text,text,text,text,text,text,text,boolean,text) from public,anon,authenticated;
grant execute on function public.update_hr_employee_v1(uuid,bigint,bigint,bigint,text,text,text,text,text,text,text,text,boolean,text) to service_role;